action.code:
size_t nbits = binfo->nbits;
size_t ngroups = BITMAP_GROUPS(nbits);
if (fill) {
    for (size_t i = 0; i < ngroups; i++) {
        bitmap[i] = ~0UL;
    }
    if (nbits % (sizeof(bitmap_t) * 8) != 0) {
        size_t trailing_bits = nbits % (sizeof(bitmap_t) * 8);
        bitmap[ngroups - 1] &= (1UL << trailing_bits) - 1;
    }
} else {
    std::memset(bitmap, 0, ngroups * sizeof(bitmap_t));
}

